# Every example in this group only reads the database (the records they refuse
# are tampered in memory), so the seed is loaded once for all of them.
RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  let(:recorded) { YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH) }

  it "exports the seeded legacy entries as stored without writing audits or billing tables" do
    connection = ActiveRecord::Base.connection
    tables = %w[audits invoices invoice_line_items invoice_line_item_time_entries invoice_taxes timesheet_entries]
    snapshot = -> { tables.index_with { |table| connection.select_rows("SELECT * FROM #{table} ORDER BY id") } }
    before = snapshot.call

    result = described_class.new(connection:, recorded_disposition: recorded)
      .export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12))

    # "Never write the legacy `audits` table." and "The source only reads billing tables; it writes none."
    expect(snapshot.call).to eq(before)

    rows = result[:checkpoint].rows
    # "Entry rows are copied as stored: `duration` as the same float, and `version` as stored (0 from the
    # column default). Nothing infers `billed` from invoice links."
    stored = TimesheetEntry.unscoped.pluck(:id, :company_id, :version, :duration, :bill_status)
      .to_h { |id, company_id, version, duration, bill_status| [id, [company_id, version, duration, bill_status]] }
    copied = rows.fetch("entries").to_h do |row|
      [row["id"], [row["company_id"], row["version"], row["duration"], row["bill_status"]]]
    end
    expect(copied).to eq(stored)
    expect(rows.fetch("entries").pluck("company_id")).to all(be_a(Integer))
    expect(rows.fetch("invoice_operations")).to eq([])
    expect(rows.fetch("idempotency_records")).to eq([])

    reserved_ids = recorded.fetch("companies").values.flat_map { |invoices| invoices.values.flat_map { |i| i["entry_ids"] } }
    committed = rows.fetch("reservations").filter_map { |r| r["entry_id"] if r["state"] == "committed" }
    expect(committed).to include(*reserved_ids)
    expect(result[:corrections].pluck("entry_id").sort).to eq(reserved_ids.sort)
  end

  # "each unlocked link follows its recorded disposition (`reserve` becomes a committed
  # reservation by that invoice). Each corrected entry gets one correction snapshot at
  # version 1 and the new generation."
  it "reserves every recorded seed unlocked link by its invoice with exactly one correction at version 1 and the passed generation" do
    captured_at = Time.utc(2026, 10, 24, 12, 0, 0)

    result = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)
      .export(generation: 7, captured_at:)

    reservations = result.fetch(:checkpoint).rows.fetch("reservations")
    corrections = result.fetch(:corrections)
    expected_entry_ids = []

    recorded.fetch("companies").each do |company_name, invoices|
      company = Company.find_by!(name: company_name)
      invoices.each do |invoice_number, listing|
        invoice = Invoice.find_by!(company_id: company.id, invoice_number:)
        listing.fetch("entry_ids").each do |entry_id|
          expected_entry_ids << entry_id
          owned = reservations.select { |row| row["entry_id"] == entry_id }
          expect(owned.size).to eq(1)
          expect(owned.first).to include(
            "company_id" => company.id, "invoice_id" => invoice.id, "state" => "committed"
          )

          entry_corrections = corrections.select { |item| item["entry_id"] == entry_id }
          expect(entry_corrections.size).to eq(1)
          correction = entry_corrections.first
          expect(correction["company_id"]).to eq(company.id)
          expect(correction["generation"]).to eq(7)
          expect(correction["snapshot"]["version"]).to eq(1)
          expect(correction["snapshot"]["locked"]).to be(true)
        end
      end
    end

    expect(expected_entry_ids).not_to be_empty
    # The seed has no re-locks, orphans or conflicts, so only reserved unlocked links are corrected.
    expect(corrections.pluck("entry_id")).to match_array(expected_entry_ids)
  end

  it "keeps every exported reservation, entry, audit and correction inside the company that owns it" do
    result = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)
      .export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12))
    rows = result.fetch(:checkpoint).rows

    entry_company = TimesheetEntry.joins(project: :client).pluck(:id, "clients.company_id").to_h
    invoice_company = Invoice.pluck(:id, :company_id).to_h

    expect(rows.fetch("reservations")).not_to be_empty
    rows.fetch("entries").each do |row|
      expect(row["company_id"]).to eq(entry_company.fetch(row["id"]))
    end
    rows.fetch("reservations").each do |row|
      expect(row["company_id"]).to eq(entry_company.fetch(row["entry_id"]))
      expect(invoice_company.fetch(row["invoice_id"])).to eq(row["company_id"])
    end
    rows.fetch("entry_audits").each do |row|
      expect(row["company_id"]).to eq(entry_company.fetch(row["entry_id"]))
    end
    result.fetch(:corrections).each do |correction|
      expect(correction["company_id"]).to eq(entry_company.fetch(correction["entry_id"]))
      expect(correction["snapshot"]["company_id"]).to eq(correction["company_id"])
    end
  end

  # "Make every derived value repeatable: a reservation's `operation_id` is a UUIDv5 of
  # company, entry and invoice, and timestamps are a capture time passed in."
  it "exports identical checkpoint rows and corrections twice from the seed with one capture time" do
    captured_at = Time.utc(2026, 10, 24, 12, 0, 0)
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    first = source.export(generation: 7, captured_at:)
    second = source.export(generation: 7, captured_at:)

    expect(second.fetch(:checkpoint).rows).to eq(first.fetch(:checkpoint).rows)
    expect(second.fetch(:checkpoint).digest).to eq(first.fetch(:checkpoint).digest)
    expect(second.fetch(:corrections)).to eq(first.fetch(:corrections))

    reservations = first.fetch(:checkpoint).rows.fetch("reservations")
    expect(reservations).not_to be_empty
    expect(reservations.pluck("created_at").uniq).to eq([captured_at])
    expect(reservations.map { |row| [row["company_id"], row["entry_id"]] }.uniq.size).to eq(reservations.size)
    expect(first.fetch(:corrections).pluck("captured_at").uniq).to eq([captured_at])
  end

  it "refuses only the company whose record names an invoice number that only the other seeded company has" do
    foreign_number = (Invoice.where(company_id: copper_kettle.id).pluck(:invoice_number) -
      Invoice.where(company_id: fork_and_leaf.id).pluck(:invoice_number)).first
    expect(foreign_number).to be_present
    recorded.fetch("companies").fetch("Fork & Leaf Salads")[foreign_number] =
      { "entry_ids" => [], "disposition" => Timekeeping::SeedDisposition::RESERVE }
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    # "Resolve an invoice number only inside the named company. Refuse, never guess, when a number is missing, matches no invoice of that company, or would link an entry to another company's invoice."
    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error).to be_a(Timekeeping::Handoff::Store::Error)
        expect(error.refusals.keys).to eq([fork_and_leaf.id])
        expect(error.refusals.fetch(fork_and_leaf.id).join("\n")).to include(foreign_number)
      }
  end

  it "lists every failing company in one refusal when both seeded companies record an unknown invoice number" do
    [fork_and_leaf, copper_kettle].each do |company|
      recorded["companies"][company.name] = (recorded["companies"][company.name] || {}).merge(
        "NO-SUCH-INVOICE-#{company.id}" => { "entry_ids" => [], "disposition" => "reserve" }
      )
    end
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    # The refusal must name both companies, not stop at the first one it meets.
    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 30, 12)) }
      .to raise_error(Timekeeping::Handoff::LegacySource::Refused) { |error|
        expect(error.refusals.fetch(fork_and_leaf.id)).to include(a_string_including("NO-SUCH-INVOICE-#{fork_and_leaf.id}"))
        expect(error.refusals.fetch(copper_kettle.id)).to include(a_string_including("NO-SUCH-INVOICE-#{copper_kettle.id}"))
        expect(error.refusals.fetch(fork_and_leaf.id)).not_to include(a_string_including("NO-SUCH-INVOICE-#{copper_kettle.id}"))
        expect(error.refusals.fetch(copper_kettle.id)).not_to include(a_string_including("NO-SUCH-INVOICE-#{fork_and_leaf.id}"))
      }
  end

  # "Cutover proceeds only when the orphan, conflict and unlocked-link lists are empty,
  # or every item has a recorded disposition."
  it "refuses both seeded companies in one error when an invoice number is filed under the other company and a link has no disposition" do
    companies = recorded.fetch("companies")
    fork_and_leaf_listing = companies.fetch("Fork & Leaf Salads").delete("FL-0001")
    # FL-0001 exists only in Fork & Leaf Salads; filed under Copper Kettle Bakery it must not resolve.
    companies.fetch("Copper Kettle Bakery")["FL-0001"] = fork_and_leaf_listing
    # Copper Kettle Bakery's own unlocked links lose their disposition.
    companies.fetch("Copper Kettle Bakery").delete("CK-0001")

    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 24, 12)) }
      .to raise_error(Timekeeping::Handoff::LegacySource::Refused) { |error|
        refusals = error.refusals
        expect(refusals.keys).to include(fork_and_leaf.id, copper_kettle.id)
        expect(refusals.fetch(fork_and_leaf.id)).not_to be_empty
        expect(refusals.fetch(copper_kettle.id).join("\n")).to include("FL-0001")
        expect(refusals.fetch(copper_kettle.id).join("\n")).to include("CK-0001")
      }
  end

  it "refuses unrecorded unlocked links in both seeded companies in one error instead of stopping at the first" do
    # Both seeded companies have unlocked links; a record that lists none leaves every one without a disposition.
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded.merge("companies" => {}))

    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error.refusals.keys).to contain_exactly(fork_and_leaf.id, copper_kettle.id)
        expect(error.refusals.values).to all(be_an(Array).and(be_present))
      }
