  it "refuses an export started inside a caller's open transaction and exports outside one" do
    connection = ActiveRecord::Base.connection
    source = described_class.new(connection:, recorded_disposition: recorded)

    # The pre-flight and the copy must read one snapshot; a caller's transaction would have fixed the
