RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "one refusal lists an orphan in one company and an unrecorded unlocked link in the other" do
    linked_ids = Timekeeping::SeedDispositionRecorder.snapshot(fork_and_leaf)[:links].pluck(:entry_id)
    orphan = TimesheetEntry.joins(project: :client).where(clients: { company_id: fork_and_leaf.id })
      .where.not(id: linked_ids).order(:id).first
    orphan.update_column(:locked, true)
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    dropped_number, = recorded["companies"].fetch("Copper Kettle Bakery").first
    recorded["companies"]["Copper Kettle Bakery"] = recorded["companies"]["Copper Kettle Bakery"].except(dropped_number)
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    # Refuse with a per-company list of the items that have none: both companies appear in the one error.
    expect { source.export(generation: 3, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(Timekeeping::Handoff::Store::Error) { |error|
        expect(error).to be_a(Timekeeping::Handoff::LegacySource::Refused)
        expect(error.refusals.fetch(fork_and_leaf.id).join("\n")).to include(orphan.id.to_s)
        expect(error.refusals.fetch(copper_kettle.id).join("\n")).to include(dropped_number.to_s)
        expect(error.refusals.fetch(copper_kettle.id).join("\n")).not_to include(orphan.id.to_s)
      }
  end
end

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "an unlisted orphan in one seeded company refuses the cutover under that company only" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    linked_ids = InvoiceLineItem.where.not(timesheet_entry_id: nil).pluck(:timesheet_entry_id) +
      InvoiceLineItemTimeEntry.pluck(:timesheet_entry_id)
    # Every seeded Copper Kettle entry is on CK-0001, so the orphan is a copy of one that no invoice links.
    linked_entry = TimesheetEntry.joins(project: :client).where(clients: { company_id: copper_kettle.id }).first
    orphan = linked_entry.dup.tap { |entry| entry.save!(validate: false) }
    expect(linked_ids).not_to include(orphan.id)
    # Locked with no invoice referencing it: an orphan, which the recorded format cannot give a disposition.
    orphan.update_columns(locked: true)
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error.refusals.keys).to eq([copper_kettle.id])
        expect(error.refusals.fetch(copper_kettle.id).join("\n")).to include(orphan.id.to_s)
      }
  end
end

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  # "Existing TimesheetEntry audit rows appear in the checkpoint with company, author, timestamps and change values, and the audits table is unchanged"
  it "exports self-created legacy entry audits from both companies with their authors and timestamps and leaves audits unchanged" do
    created_at = Time.utc(2025, 3, 4, 5, 6, 7)
    audits = [fork_and_leaf, copper_kettle].map do |company|
      entry = TimesheetEntry.joins(project: :client).where(clients: { company_id: company.id }).order(:id).first
      audit = Audited::Audit.create!(
        auditable_type: "TimesheetEntry", auditable_id: entry.id, associated_type: "Company",
        associated_id: company.id, user_type: "User", user_id: entry.user_id, action: "update",
        audited_changes: { "note" => ["before note", "after note"] }, created_at:
      )
      [audit, entry, company]
    end
    audits_before = Audited::Audit.order(:id).map(&:attributes)

    result = described_class.new(
      connection: ActiveRecord::Base.connection,
      recorded_disposition: YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    ).export(generation: 3, captured_at: Time.utc(2026, 10, 25, 12, 0, 0))

    rows = result[:checkpoint].rows.fetch("entry_audits")
    audits.each do |audit, entry, company|
      row = rows.find { |candidate| candidate["id"] == audit.id }
      expect(row).to include(
        "company_id" => company.id, "entry_id" => entry.id, "actor_type" => "user", "actor_id" => entry.user_id,
        "action" => "update", "before" => { "note" => "before note" }, "after" => { "note" => "after note" }
      )
      expect(row["created_at"]).to eq(created_at)
      expect(row["entry_created_at"]).to eq(entry.created_at)
    end
    expect(Audited::Audit.order(:id).map(&:attributes)).to eq(audits_before)
  end
end

RSpec.describe Timekeeping::Handoff::LegacySource, :without_transaction do
  let(:stored_rows) do
    connection = ActiveRecord::Base.connection
    lambda do
      %w[audits invoices invoice_line_items invoice_line_item_time_entries invoice_taxes timesheet_entries].index_with do |table|
        connection.select_all("SELECT * FROM #{connection.quote_table_name(table)} ORDER BY id").to_a
      end
    end
  end

  # "Never write the legacy `audits` table."
  # "The source only reads billing tables; it writes none."
  it "refuses an unlisted orphan for its company and writes no audit or billing row" do
    connection = ActiveRecord::Base.connection
    company = create(:company)
    project = create(:project, client: create(:client, company:), billable: true)
    orphan = create(:timesheet_entry, user: create(:user, current_workspace_id: company.id), project:, bill_status: "unbilled")
    orphan.update_columns(locked: true, company_id: company.id)

    before = stored_rows.call
    source = described_class.new(connection:, recorded_disposition: { "as_of" => "2026-10-23", "companies" => {} })

    expect { source.export(generation: 2, captured_at: Time.utc(2026, 10, 25)) }
      .to raise_error(Timekeeping::Handoff::LegacySource::Refused) { |error|
        expect(error).to be_a(Timekeeping::Handoff::Store::Error)
        expect(error.refusals.keys).to eq([company.id])
        expect(error.refusals.fetch(company.id).join(" ")).to include(orphan.id.to_s)
      }
    expect(stored_rows.call).to eq(before)
  end

  # "Entry rows are copied as stored: `duration` as the same float, and `version` as stored (0 from the column default). Nothing infers `billed` from invoice links."
  # "Each recorded unlocked link with disposition reserve becomes a committed reservation by that invoice with exactly one correction snapshot at version 1 and the new generation"
  it "exports entries as stored and every legacy audit, leaves the database unchanged, and gives the same checkpoint on a repeat export" do
    connection = ActiveRecord::Base.connection
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    entry = create(:timesheet_entry, user: create(:user, current_workspace_id: company.id), project:, bill_status: "unbilled")
    invoice = create(:invoice, company:, client:, status: "sent")
    create(:invoice_line_item, invoice:, timesheet_entry: entry, rate: 100, quantity: 60)
    entry.update_columns(locked: false, company_id: company.id, duration: 0.30000000000000004, bill_status: TimesheetEntry.bill_statuses["unbilled"])

    before = stored_rows.call
    legacy_audit_count = connection.select_value("SELECT count(*) FROM audits WHERE auditable_type = 'TimesheetEntry'").to_i
    recorded = {
      "as_of" => "2026-10-23",
      "companies" => { company.name => { invoice.invoice_number => { "entry_ids" => [entry.id], "disposition" => "reserve" } } }
    }
    captured_at = Time.utc(2026, 10, 25, 12, 0, 0)
    source = described_class.new(connection:, recorded_disposition: recorded)

    first = source.export(generation: 7, captured_at:)
    second = source.export(generation: 7, captured_at:)

    rows = first[:checkpoint].rows
    copied = rows.fetch("entries").find { |row| row["id"] == entry.id }
    expect(copied["company_id"]).to eq(company.id)
    expect(copied["version"]).to eq(0)
    expect([copied["duration"]].pack("G")).to eq([0.30000000000000004].pack("G"))
    expect(copied["bill_status"]).to eq("unbilled")
    expect(copied["locked"]).to be(false)

    expect(rows.fetch("reservations").map { |row| row.values_at("company_id", "entry_id", "invoice_id", "state", "created_at") })
      .to eq([[company.id, entry.id, invoice.id, "committed", captured_at]])
    expect(first[:corrections].map { |correction| correction.values_at("company_id", "entry_id", "generation") }).to eq([[company.id, entry.id, 7]])
    expect(first[:corrections].first["snapshot"]["version"]).to eq(1)

    expect(rows.fetch("entry_audits").size).to eq(legacy_audit_count)
    expect(rows.fetch("entry_audits").pluck("company_id")).to all(eq(company.id))
    expect(rows.fetch("invoice_operations")).to eq([])
    expect(rows.fetch("idempotency_records")).to eq([])

    expect(second[:checkpoint].digest).to eq(first[:checkpoint].digest)
    expect(second[:checkpoint].rows).to eq(rows)
    expect(second[:corrections]).to eq(first[:corrections])
    expect(stored_rows.call).to eq(before)
  end

  # A recorded listing filed under a name no company has, or a name two companies share,
  # could otherwise be applied to the wrong company.
  it "refuses a recorded company name that matches no company or more than one, keyed by that name" do
    shared_name = "Twin Bakery"
    create(:company, name: shared_name)
    create(:company, name: shared_name)
    recorded = {
      "as_of" => "2026-10-23",
      "companies" => { shared_name => {}, "Nobody Here" => {} }
    }
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error.refusals.keys).to contain_exactly(shared_name, "Nobody Here")
        expect(error.refusals.fetch(shared_name).join("\n")).to include("matches 2 companies")
        expect(error.refusals.fetch("Nobody Here").join("\n")).to include("matches 0 companies")
      }
  end
end
